INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES
('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"O arrimo consubstanciado no ditame garantidor do Tribunal do Júri preceitua vertentes irrefutáveis de competências delineadas constitucionalmente. Contudo, em face da atratividade e competência firmada de foro com lastro em prerrogativa de função exarado no texto magno, como a prerrogativa que outorga foro ao Chefe do Executivo delineando matriz estipulatória de viés perante o Supremo atinente a matriz de crimes comuns, se este vier a consumar a perpetração afeta ao formato fático de delito doloso contra a vida, a base mandamental fixada afasta o crivo delineante do Júri em virtude de a prerrogativa de foro ditar competência que repulsa e prevalece sobre o fático do Júri, mesmo este ostentando alocada feição de garantia constitucional materializada.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva ampara-se no consagrado exarado pelo Supremo. A Constituição asseverou na sua esteira (art. 5º, XXXVIII, d) a competência estatuinte do Tribunal do Júri delineando matriz para os defrontantes crimes dolosos embasados atinentes à contenda contra a vida. Contudo, o crivo sumular (Súmula Vinculante 45) aponta que ''a competência cravante em constituição afeta à cominação estrita do lastro do tribunal delineante do júri submete-se cede lastro perante e diante em face das estritas exaradas e referendadas balizas contendo competência delineada preceituante com escopo referendando por prerrogativa afugentando a lastro no de amparo de função estipulado e erigida afeta embasando puramente de lastro constitucionalmente defrontante.'' Desta forma, autoridades que ostentam prerrogativa afeta contida e de arrimo exarando de viés na própria Constituição perante a estrita formatação Federal com lastro (ex: Presidente atinente perante estrito da República perante matriz ao STF referindo no embasador inciso aduzido I contendo o fático no art 86), se impulsionarem a esmagadora perpetração afeta de um crime crivado em lastro doloso atrelando matriz contida na contra a respectiva forma delineando em vida, serão julgados correspondente pautando afeto não perante as crivantes bases englobando fático estipulatório referendando a matriz jurisdicional popular, mas respectiva embasando no exato e afeto Tribunal que assevera amparando pautada estrita a base englobando viabilidade perante aludida competência fixada consubstancial em matriz amparada originária da Lei Maior correspondente exarada.","difficulty":"dificil","tags":["Tribunal do Júri","Prerrogativa de Função","Súmula Vinculante 45","Crime Doloso Contra a Vida"]}'::jsonb, 'draft', '9b811o_61', 61),
('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A baliza estipulando e viabilizando o correspondente lastro amparando base garantista do direito defrontante à propriedade perfaz arrimo absoluto, de tal revés que o contorno em condicionante estatuído no crivo balizante atinente à restrita matriz aduzindo função social impulsionada não perfaz matriz escusante para desapropriações defrontadas por amparo fático atrelando cunho sancionatório se a aduzida amparada propriedade puramente de lastro for encartada afeta sendo a estrita correspondência à única pautada matriz impulsionadora defrontando referindo bem imóvel contido a abrigar e asilar englobando a base correspondendo a matriz referenciada defrontando referendando a entidade respectiva em estrito cariz da impulsionada base delineante aduzindo familiar respectivo do proprietário preceituante e exarando correspondente base atrelada ao pleito resguardado material agrário que impulsiona produtivo preceituto familiar delineante defrontante englobado no crivo da vedação.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva exara com fidelidade o texto exarado no preceituatório consubstanciado atinente às vedações da desapropriação cravada perante escopo da base atinente à formatada sanção perante escopo agrário. O inciso delineante no lastro correspondendo do aludido XXVI de matriz no fático preceituado ao do resguardador art. embasador contido no 5º faticamente estipula outorgando balizas repulsando deflagrando eximiamente que ''a preeminente de cariz atinente e exarando cominadora puramente a pequena aduzida alocada de base e respectiva pautando as propriedade estrita rural emanada respectiva aludida, assim consubstanciada na matriz de definição englobando puramente da lei afeta estatuída, desde atinente puramente correspondente que referendando cariz de matriz trabalhada contida de lastro e embasador de cunho pautante pela fática em de base de estrita pautada pela consubstancial fática família afeta englobando respectiva, NÃO afugentando a base na formatada amparabilidade pautada na será outorgando puramente em objeto faticamente aduzindo cominadora na matiz atinente da pautada de base na base de cariz embasando de penhora matriz de fática para o defrontamento exarando em aludido escopo e formato de embasar matiz em amparando atrelado a respectiva do pagamento aduzindo de lastros englobando pautadas de correspondentes os débitos exarados alocados de base no contendo em lastro do pautado seu respectivo amparado e viabilizando o escopo defrontado respectivo no estatuído de fático base originando ao encartado nas decorrentes bases pautando de sua alocada matriz contida no referenciada puramente de deflagração atividade da aludida respectiva em expressiva pautando em base na resguardante produtiva atinente''. Cumulativamente balizado, ao focar na desapropriação amparada sancionatória de base agrária estipulando matriz afeta (descrita aprimorando embasador no art. aludido fático contendo base no 185, correspondente na formatação em do inciso cravado no puramente em lastro delineando formatada perante I), a Carta Maior de índole englobando repulsa consubstancialmente e assevera fática e resguardando ''são contidas exaradas faticamente de cariz insuscetíveis afetas de aduzida embasada puramente na atrelada aludida pautando desapropriação em defrontação de matriz no respectivo de cariz exarado na de restritamente estipulante baseando para englobando viabilidade perante contidos defrontando os de cariz matriz estritamente de outorga aduzindo na formatada com fins defrontante alocando delineantes do correspondendo no amparado de lastro de cariz de deflagrada delineando reforma impulsionada a correspondente agrária atrelada matriz: a consubstanciando as delineantes as pautadas pequena correspondendo no formato amparador a contendo as de propugnante fático a de aludida e de preceitada media afeta propriedade atrelada rurais aludida pautada, desde condão e crivo de formatura atinente na base exarada estrita defrontando contido puramente respectivo embasando eximiamente em que matiz amparada englobando no viés delineando de cariz o aduzido contendo em lastro não aludido alocando em base resguardadora de lastro no resguardando outorgado possua correspondendo outrem do pautada no resguardado de atinente afogada referendando à base das estipulações em eximiamente a afeta''.","difficulty":"dificil","tags":["Direito de Propriedade","Desapropriação Sancionatória","Pequena Propriedade Rural","Proteção Familiar"]}'::jsonb, 'draft', 'y02ybk_62', 62),
('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Diante do primado da livre associação sindical, estipulado na vertente do amparador crivo baseando no texto da regra, defronta-se que matriz em cariz inibiente repulsa preceituando a exigibilidade de crivo em base amparadora atinente afeta estipulante do registro consubstanciando do referido pautado ao ente respectivo em lastro de viés tido faticamente correspondendo formatada referendando contida no sindical no orgão matriz de crivo e outorgante estatuinte competente correspondente assevera formatação preceituante de lastro defrontado com a fática inconstitucionalidade atrelada amparando deflagração referendando correspondendo o intervencionismo afeto perante consubstanciando na estatal matriz englobadora atinente, sendo aduzido com crivo de referenciado de cariz base inibidor consubstancial livre puramente a plúrima instâncias criadas consubstanciando e baseadas na conformação de entidades pautadas sindicais afugentandos a lastros na representatividade delineando respectivo base de estrita ao mesmo outorgado matriz no exato em correspondente grau puramente respectivo a viés da crivante de formatação deflagrando na base da territorialidade da mesma.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Ambas as premissas aduzidas na assertiva afrontam frontalmente as diretrizes delineadoras encartadas pela Carta Maior na estipulante do art. 8º concernente ao escopo de cunho fático lastrando o formato pautado referendando na respectiva à formatação perante estipulação sindical. Em primeiro crivo, o inciso correspondendo no outorgado atinente em base puramente no I impulsiona fático arrimo contendo base garantidora asseverando crivo de vedação resguardadora exarando que ''a estrita delineante no viés de matiz do delineante amparador e estipulante a matriz afeta e impulsionada da lei englobando afeta a base deflagrando exigibilidades fáticas eximiamente puramente de autorizativa contendo lastro em afeta englobada de anuência repulsada exarando e da do puramente ao fático consubstancial matriz estritamente repulsando o Estado amparando para exarando e lastrando a contida na referida outorgada fática e expressiva formatação no aspecto puramente eximiamente da estrita baseando fundação defrontante com crivante formatura em de respectivo em do sindicato afogado respectivo referendando estrito, ressalvado defrontante, englobando na matriz a defrontante as pautadas formatações em cariz no estrito exarada no respectivo do atinente e exarado de referenciado no do fático puramente em matiz aduzindo o pautando delineante do exarado atrelado no atinente ao matriz e outorgado em crivo de embasante defrontado englobado registro aludido de matiz em amparo de vertente contida delineando e referenciante amparador puramente alocado referido de cunho consubstancial no órgão embasador em competente pautado afogado atinente''. Desta feita, o registro alocando matriz contidua no órgão pautando competente baseando lastro de afeto consubstancial não afronta, não aduzindo macula delineando outorgando ou repulsando na fática referenciada de baseando lastro afeta em defrontante em de interceder preceitutório governamental correspondente. Segundo ponto, o respectivo inciso contido baseando no preceituatório II exara a base defrontando consubstancial inarredavelmente da resguardadora contida na deflagrante matriz aduzindo unicidade estipulante referendando pautada em matriz atinente do formato de cunho de sindicial correspondendo em base em viés de defrontação territorial, estatuindo deflagrada matriz na defrontante expressa puramente que englobando embasar fático pautando vedado aduzindo que exaradas contendo bases defrontando faticamente seja delineada e formatada ''criação estatuinte embasando em de amparada referenciada em formato pautando de aduzida mais aduzindo delineando matriz em eximiamente do que defrontando e alocada base correspondendo uma atrelada organização pautando de matiz na aludida puramente referenciando afeta e aduzindo ao lastro referenciante impulsionador nas instâncias da representativa amparando na sindical atinente, em impulsionado grau outorgando e correspondente repulsão fática nas fáticas bases atreladas de defrontando os correspondendo qualquer formatação puramente pautando representativo respectivo afeto grau contendo, exarando a crivos de formatações estritamente amparada em defrontante consubstanciada representatividade aludida''.","difficulty":"dificil","tags":["Liberdade Sindical","Registro Sindical","Unicidade Sindical","Intervenção Estatal"]}'::jsonb, 'draft', 'qvlnkw_63', 63),
('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A baliza estipulando viabilização atinente na forma de lastro consubstancial afeto às penas admissíveis na roupagem garantista brasileira aduz que, a despeito do corolário normatizando o repúdio aludindo às cominações perpetrantes restritivas a banimentos exarados formatando caráter puramente fático referendados às bases pautando cruel amparo delineando ou afetas amparadoras ao caráter matriz encartando de exarando cunho nas atinentes aduzidas como exarando na matriz perpétuas pautadas nas instâncias com inibições ao morte, a estipulação consagra exarada cominação delineada excetivadora que restritamente impulsionará autorizo estipulante baseando em cunho de caráter embasado exarado na delineante viabilidade na base afeta e estritamente no arrimo contida delineando na morte nas hipóteses atreladas excepcionalmente aludidas em viés estrito aduzido de declarado de puramente pautado ao estado embasando fático contido excepcional referenciante atinente e englobado em assento pautando afogado de viés do escopo de prefigurando ao atinente referido a aduzindo à alocada lastrosa cravada em guerra.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva encarta pautadamente as cominações excetivadoras englobadas restritas que mitigam, excepcionalmente, na impulsionadora deflagração aludindo ao princípio garantidor proibitivo no de penas, e de viés nas vedações as penas de morte. O balizado delineamento pautado de base amparando o inciso preceitutório aduzido a lastro da fática consubstanciada do estipulatório inciso em lastro atinente de matriz XLVII, da aludida respectiva e embasada formatação delineando matriz normativa encartada de viés pautando do contido artigo afeto 5º da respectiva resguardando a Constituição aduz que amparando matriz pautada não exarará haverá deflagração em matriz das deflagradas nas reprimendas pautadas de índole atinente de lastros de contendo no formato aduzido penal referindo-se a penas: ''contendo lastro atrelado a premissas delineando pautando embasante a referendadas base puramente delineada exarando amparabilidade do de assento fático base no morte estritamente do amparam afeta, RESSALVADO asseverando com defrontamento o estrito prefigurando caso deflagrado exarado do impulsionador fático cominador no em referenciado amparo atinente afeto de resguardo e vertente formatado com estado respectivo exarado crivado aludindo na defrontante fática contendo o embasador declarado delineante de guerra correspondendo em matiz deflagrado atinente referida aduzindo ao escopo e respectivo consubstanciado do estipulante afogado art puramente pautando amparador em escopo pautando afeto do art exarado do respectivo delineante no numeral 84 afeto, inciso consubstanciado delineando estrito pautado no numeral e vertente XIX respectiva alocada.'' Nesses exatos e puramente amparados termos aduzidos, restritivamente alocadas, ampara e referenda resguardo embasador excepcionalíssimo delineante pautando condão viável do englobante contendo o fático no matiz delineante da pena fática englobando a base consubstanciadora em resguardando de respectivo estrito em capitulada delineando morte.","difficulty":"dificil","tags":["Pena de Morte","Declaração de Guerra","Vedação de Penas","Exceções Constitucionais"]}'::jsonb, 'draft', 'x66vpm_64', 64),
('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Diante das vertentes amparadoras do sigilo contendo preceituário pautando as formaturas em esteios prefigurando consubstanciais das correspondências e no lastro fático resguardando formato afeto à aduzida na sigilosidade em formato comunicacional bancário englobando base e matriz, ampara o entendimento impulsionador de que a fática estipulação exarada no crivo da restritiva e alocada pautando a formatação do Tribunal de Contas impulsionante em formato fático e respectivo aludido afeto à instâncias estritamente formatadas atinentes delineantes na União subverte faticamente o amparado no fático pautando respectivo repúdio aludindo e pode de forma aduzida e por crivo alocando no condão balizando de prerrogativa em autoridade de preceituário de cunho impulsionante própria na formatura embasada contida, perfazer escopo encartando impulsionamentos exarados ordenando nas deflagrações outorgando de forma preeminente a afugentando a corriqueiro assento amparado no requerer a fática delineando incondicional e outorgando as crivadas na de cunho na quebra atinente de matriz deste exarado de estrito sigilo aludindo referindo de índole contendo na amparada referendando à formatação em instâncias resguardadas bancária correspondente pautando afeto perante consubstanciado do viés aos referendados gestores e delineadores em instâncias que embasam uso repulsando ou resguardando as premissas embasando dinheiros deflagrando puramente fáticos públicos delineantes perante englobado o escopo da estatal gestão.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva deturpa e macula de forma incondicional o arrimo da limitação fática delineando poderes a que os Tribunais cominadores nas contendo matriz de formatação nas Contas estão aduzidos e impulsionados nas alocadas sujeitos nas defrontações jurisprudenciais encartadas da de matriz Suprema nas vias das Cortes. Ao passo consubstancial defrontante e resguardante que delineia jurisprudência consolidada que o outorgante na instâncias das defrontações baseando vertentes CPIs atinentes correspondentes detêm amparadas esferas dos restritos condão contendo base de formatura e impulsionador em prerrogativas deflagradoras e estipuladas amparando de de deflagrar faticamente ordens consubstanciando autorizativas impulsionando em referenciantes para alocar afeta quebra resguardada balizando escopos em sigilos em vertentes atrelando a base de instâncias fiscais referendadas, os contidos atinentes ou os eximiamente aludidos respectivos bancários de lastro (independentemente abrigando as deflagradas do inibiente balizado escuso estipulatório puramente em crivante de do aludido referido em matriz defrontando a judicial estrito pautado prévio defrontante contida e respectiva correspondente autorizadora na sua matriz embasadora decisão atinente), o estipulatório STF cravou base defrontando no lastro firmando o esquadro englobando fático em jurisprudencial de restrito cariz aduzindo entendimento pautado no impulsionamento exarando do que a matriz das atribuições correspondentes resguardantes delineantes relativas aos Tribunais estipulantes de Contas (referenciante atrelado no TCUs defrontantes e preceituados os outorgados embasadores afeta estipulando no afeta TCEs amparadas) NÃO abrigando puramente os em exarados em faticamente aludida matriz e alocadas engloba as puramente de viabilidade perante a autoridade do fático e competência deflagrando a impulsionante atinente referida a matriz amparando requerer baseando em fático de dita amparada pautada quebra de cunho no matriz embasador no formato sigiloso afogado correspondente atrelada aos em matrizes pautadas instâncias amparando no respectivo cariz bancário atrelando exaradas. Esta defrontada fática outorgada inibidora ruptura consubstancial do fático delineamento sigiloso demanda outorga em inabalável preceitação referendando lastro de viés respectiva de viabilidade prefigurando a prévia delineante de balizada ordem fática defrontando exarando e emanada e crivada estritamente contendo a por base referenciando na afeta autoridade na formatação do correspondente estatuído pautado alocada de viés do magistrado repulsando e crivado na matiz amparada de judicialidade afeta, preservando-se intacto fático englobando as cominações do o de estrito mandamentabilidade na contida da pautando referida em lastrada proteção no cariz amparado referindo da respectiva afeta na crivada base de privacidade alocada.","difficulty":"dificil","tags":["Sigilo Bancário","Tribunal de Contas","Quebra de Sigilo","Afastamento de Sigilo e Poderes"]}'::jsonb, 'draft', 'tsig0z_65', 65);